-- Schema snapshot: the database after migration 0034, as SQLite stores it,
-- with each column and table constraint on its own line.
-- Generated by db::tests::schema_snapshot_matches_migrations; do not edit by hand.
-- Regenerate: RUNNER_UPDATE_GOLDEN=1 cargo test -p runner-daemon schema_snapshot

CREATE TABLE _app_state (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
);

CREATE TABLE _migrations (
    version INTEGER PRIMARY KEY,
    applied_at TEXT NOT NULL
);

CREATE TABLE crews (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    system_prompt_addendum TEXT
);

CREATE TABLE mission_budget_basis (
    mission_id TEXT NOT NULL REFERENCES missions(id) ON DELETE RESTRICT,
    runtime TEXT NOT NULL,
    read_at TEXT NOT NULL,
    week_start TEXT NOT NULL,
    mission_input INTEGER NOT NULL,
    mission_output INTEGER NOT NULL,
    mission_cached INTEGER NOT NULL,
    mission_reasoning INTEGER NOT NULL,
    machine_input INTEGER NOT NULL,
    machine_output INTEGER NOT NULL,
    machine_cached INTEGER NOT NULL,
    machine_reasoning INTEGER NOT NULL,
    PRIMARY KEY (mission_id, runtime, read_at)
);

CREATE TABLE mission_budget_sample (
    mission_id TEXT NOT NULL REFERENCES missions(id) ON DELETE RESTRICT,
    runtime TEXT NOT NULL,
    window_name TEXT NOT NULL,
    used_percent REAL NOT NULL,
    resets_at TEXT,
    read_at TEXT NOT NULL,
    kind TEXT NOT NULL CHECK (kind IN ('start', 'join', 'view', 'stop')),
    PRIMARY KEY (mission_id, runtime, window_name, read_at)
);

CREATE TABLE mission_rating (
    mission_id TEXT PRIMARY KEY REFERENCES missions(id) ON DELETE RESTRICT,
    verdict TEXT NOT NULL CHECK (verdict IN ('up', 'down')),
    note TEXT NOT NULL DEFAULT '',
    rated_at TEXT NOT NULL
);

CREATE TABLE mission_slot_usage (
    mission_id TEXT NOT NULL REFERENCES missions(id) ON DELETE RESTRICT,
    handle TEXT NOT NULL,
    runtime TEXT,
    model TEXT,
    effort TEXT,
    prompt_hash TEXT,
    input_tokens INTEGER,
    output_tokens INTEGER,
    cached_tokens INTEGER,
    reasoning_tokens INTEGER,
    steps INTEGER,
    input_includes_cached INTEGER,
    wall_minutes REAL,
    not_recorded_reason TEXT,
    recorded_at TEXT NOT NULL,
    PRIMARY KEY (mission_id, handle)
);

CREATE TABLE mission_usage_call (
    mission_id TEXT NOT NULL REFERENCES missions(id) ON DELETE RESTRICT,
    usage_id TEXT NOT NULL,
    runtime TEXT NOT NULL,
    session_key TEXT NOT NULL,
    at TEXT NOT NULL,
    input_tokens INTEGER NOT NULL,
    output_tokens INTEGER NOT NULL,
    cached_tokens INTEGER NOT NULL,
    reasoning_tokens INTEGER NOT NULL,
    PRIMARY KEY (mission_id, usage_id)
);

CREATE TABLE "missions" (
    id TEXT PRIMARY KEY,
    crew_id TEXT,
    title TEXT NOT NULL,
    status TEXT NOT NULL,
    goal_override TEXT,
    cwd TEXT,
    started_at TEXT NOT NULL,
    stopped_at TEXT,
    pinned_at TEXT,
    archived_at TEXT,
    project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,
    linked_session_id TEXT REFERENCES sessions(id) ON DELETE SET NULL,
    report_to_chat INTEGER NOT NULL DEFAULT 1,
    files_root TEXT
);

CREATE INDEX idx_missions_linked_session ON missions(linked_session_id);

CREATE INDEX idx_missions_project ON missions(project_id);

CREATE TABLE nodes (
    id                 TEXT PRIMARY KEY,
    parent_id          TEXT REFERENCES nodes(id) ON DELETE RESTRICT,  -- NULL = root
    position           INTEGER NOT NULL,  -- scoped to parent
    type               TEXT NOT NULL,  -- 'folder' | 'project' | 'tab' | 'mission'
    name               TEXT,  -- folder/tab title (project/mission names live on their domain rows)
    ref_id             TEXT,  -- projects.id / missions.id for reference types
    layout             TEXT,  -- tab-only: pane layout JSON (as tabs.layout today)
    pinned_position    INTEGER,  -- non-NULL = pinned; value orders the PINNED section
    last_completed_at  TEXT,  -- tab-only attention watermarks (from 0010)
    last_viewed_at     TEXT,
    created_at         TEXT NOT NULL
);

CREATE INDEX idx_nodes_parent_position ON nodes(parent_id, position, created_at);

CREATE TABLE projects (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    cwd TEXT NOT NULL,
    position INTEGER NOT NULL,
    created_at TEXT NOT NULL
);

CREATE INDEX idx_projects_position ON projects(position, created_at);

CREATE TABLE "roles" (
    id TEXT PRIMARY KEY,
    handle TEXT NOT NULL UNIQUE,
    display_name TEXT NOT NULL,
    runtime TEXT NOT NULL,
    command TEXT NOT NULL,
    args_json TEXT,
    working_dir TEXT,
    system_prompt TEXT,
    env_json TEXT,
    model TEXT,
    effort TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    runtime_options_json TEXT
);

CREATE TABLE "session_attention" (
    session_id TEXT PRIMARY KEY REFERENCES sessions(id) ON DELETE RESTRICT,
    unread_since INTEGER,
    error_acknowledged_at TEXT
);

CREATE TABLE "sessions" (
    id TEXT PRIMARY KEY,
    mission_id TEXT REFERENCES missions(id) ON DELETE SET NULL,
    role_id TEXT REFERENCES "roles"(id) ON DELETE RESTRICT,
    slot_id TEXT,
    cwd TEXT,
    status TEXT NOT NULL,
    pid INTEGER,
    started_at TEXT,
    stopped_at TEXT,
    agent_session_key TEXT,
    archived_at TEXT,
    title TEXT,
    pinned_at TEXT,
    agent_runtime TEXT,
    agent_command TEXT,
    project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,
    last_cols INTEGER,
    last_rows INTEGER,
    resume_on_launch INTEGER NOT NULL DEFAULT 0,
    live_title TEXT,
    launch_definition_json TEXT,
    files_root TEXT
);

CREATE INDEX idx_sessions_project ON sessions(project_id);

CREATE TABLE "slots" (
    id TEXT PRIMARY KEY,
    crew_id TEXT NOT NULL REFERENCES crews(id) ON DELETE RESTRICT,
    role_id TEXT NOT NULL REFERENCES "roles"(id) ON DELETE RESTRICT,
    slot_handle TEXT NOT NULL,
    position INTEGER NOT NULL,
    lead INTEGER NOT NULL DEFAULT 0,
    added_at TEXT NOT NULL,
    runtime_override TEXT,
    model_override TEXT,
    effort_override TEXT,
    runtime_options_json TEXT,
    UNIQUE (crew_id, slot_handle),
    UNIQUE (crew_id, position)
);
